/**
 * Pure D14-F02-A01 inverse-volatility allocator.
 *
 * Only ordered IDs and finite, strictly positive standalone volatilities are
 * accepted. Estimation, provenance, holdings/FX valuation, and covariance
 * diagnostics are deliberately outside this core module.
 */

export const WEIGHT_SUM_ABSOLUTE_TOLERANCE = 1e-12;
export const COMPARISON_ABSOLUTE_TOLERANCE = 1e-10;
export const COMPARISON_RELATIVE_TOLERANCE = 1e-8;

export type InverseVolatilityErrorCode = "invalid-input" | "numerical-range-invalid";

export interface InverseVolatilityResult {
  assetIds: string[];
  weights: number[];
  normalizedInverseVolatilityScores: number[];
  sumWeights: number;
  method: "inverse-volatility";
  status: "ok";
}

export class InverseVolatilityValidationError extends Error {
  readonly code: InverseVolatilityErrorCode;

  constructor(code: InverseVolatilityErrorCode, message: string) {
    super(message);
    this.name = "InverseVolatilityValidationError";
    this.code = code;
  }
}

function invalid(code: InverseVolatilityErrorCode, message: string): never {
  throw new InverseVolatilityValidationError(code, message);
}

function neumaierSum(values: readonly number[]): number {
  let total = 0;
  let compensation = 0;
  for (const value of values) {
    const candidate = total + value;
    if (Math.abs(total) >= Math.abs(value)) {
      compensation += (total - candidate) + value;
    } else {
      compensation += (value - candidate) + total;
    }
    total = candidate;
  }
  return total + compensation;
}

/**
 * Return normalized inverse-volatility weights in the caller's exact order.
 * The stable score is min(sigma) / sigma[i]. A positive mathematical score
 * that becomes zero through floating-point underflow is a range failure.
 */
export function inverseVolatilityWeights(
  assetIds: readonly unknown[],
  standaloneVolatilities: readonly unknown[],
): InverseVolatilityResult {
  if (!Array.isArray(assetIds)) {
    invalid("invalid-input", "assetIds must be an ordered array.");
  }
  if (!Array.isArray(standaloneVolatilities)) {
    invalid("invalid-input", "standaloneVolatilities must be an ordered numeric array.");
  }
  if (assetIds.length === 0) {
    invalid("invalid-input", "the asset universe must not be empty.");
  }
  if (assetIds.length !== standaloneVolatilities.length) {
    invalid("invalid-input", "assetIds and volatilities must have equal length.");
  }

  const ids: string[] = [];
  for (let index = 0; index < assetIds.length; index += 1) {
    const value = assetIds[index];
    if (typeof value !== "string" || value.trim() === "") {
      invalid("invalid-input", `assetIds[${index}] must be a non-empty string.`);
    }
    ids.push(value);
  }
  if (new Set(ids).size !== ids.length) {
    invalid("invalid-input", "assetIds must be unique.");
  }

  const volatilities: number[] = [];
  for (let index = 0; index < standaloneVolatilities.length; index += 1) {
    const value = standaloneVolatilities[index];
    if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
      invalid(
        "invalid-input",
        `standaloneVolatilities[${index}] must be finite and positive.`,
      );
    }
    volatilities.push(value);
  }

  let minimumVolatility = Number.POSITIVE_INFINITY;
  for (const volatility of volatilities) {
    if (volatility < minimumVolatility) {
      minimumVolatility = volatility;
    }
  }
  const scores = volatilities.map((volatility) => minimumVolatility / volatility);
  if (scores.some((score) => !Number.isFinite(score) || score <= 0)) {
    invalid(
      "numerical-range-invalid",
      "a positive normalized inverse-volatility score underflowed or became non-finite.",
    );
  }

  const scoreSum = neumaierSum(scores);
  if (!Number.isFinite(scoreSum) || scoreSum <= 0) {
    invalid(
      "numerical-range-invalid",
      "the normalized inverse-volatility score sum is non-finite or non-positive.",
    );
  }

  const weights = scores.map((score) => score / scoreSum);
  if (weights.some((weight) => !Number.isFinite(weight) || weight <= 0)) {
    invalid(
      "numerical-range-invalid",
      "a positive normalized weight underflowed or became non-finite.",
    );
  }

  const sumWeights = neumaierSum(weights);
  if (!Number.isFinite(sumWeights)) {
    invalid("numerical-range-invalid", "the weight sum is non-finite.");
  }
  if (Math.abs(sumWeights - 1) > WEIGHT_SUM_ABSOLUTE_TOLERANCE) {
    invalid(
      "numerical-range-invalid",
      "normalized weights do not satisfy the frozen sum tolerance.",
    );
  }

  return {
    assetIds: ids,
    weights,
    normalizedInverseVolatilityScores: scores,
    sumWeights,
    method: "inverse-volatility",
    status: "ok",
  };
}
